public static class RpgImageSkin {
static string folder="Assets/00_ProjectD/04_UI/Skin/";
static T C<T>(Transform t) where T:Component {t.TryGetComponent<T>(out var c);return c;}
static void P(Transform t,float x,float y,float w,float h){var r=(RectTransform)t;r.anchorMin=r.anchorMax=new Vector2(0,1);r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);}
static Sprite S(string n)=>AssetDatabase.LoadAssetAtPath<Sprite>(folder+n+".asset");
static void Skin(Transform t,string n,bool sliced=false){var im=C<UnityEngine.UI.Image>(t);im.enabled=true;im.sprite=S(n);im.type=sliced?UnityEngine.UI.Image.Type.Sliced:UnityEngine.UI.Image.Type.Simple;im.color=Color.white;if(t.TryGetComponent<RpgGradient>(out var g))Object.DestroyImmediate(g);}
static void Icon(Transform t,string n){foreach(var c in t.GetComponents<UnityEngine.UI.Graphic>())Object.DestroyImmediate(c);var im=t.gameObject.AddComponent<UnityEngine.UI.Image>();im.sprite=S(n);im.preserveAspect=true;im.raycastTarget=false;}
static Transform Child(Transform p,string n){var t=p.Find(n);if(t)return t;var go=new GameObject(n,typeof(RectTransform),typeof(UnityEngine.UI.Image));go.layer=5;go.transform.SetParent(p,false);C<UnityEngine.UI.Image>(go.transform).raycastTarget=false;return go.transform;}
static Texture2D Import(string n){var path=folder+n+".png";var i=(TextureImporter)AssetImporter.GetAtPath(path);i.textureType=TextureImporterType.Default;i.alphaIsTransparency=true;i.mipmapEnabled=false;i.textureCompression=TextureImporterCompression.Uncompressed;i.filterMode=FilterMode.Bilinear;i.maxTextureSize=2048;i.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
static void Slice(Texture2D texture,string n,float x,float y,float w,float h,Vector4 border=default){string path=folder+n+".asset";if(AssetDatabase.LoadAssetAtPath<Sprite>(path))return;float sx=texture.width/1280f,sy=texture.height/1280f;var s=Sprite.Create(texture,new Rect(x*sx,(1280-y-h)*sy,w*sx,h*sy),new Vector2(.5f,.5f),100,0,SpriteMeshType.FullRect,border);s.name=n;AssetDatabase.CreateAsset(s,path);}
public static void Import(){AssetDatabase.Refresh();var f=Import("PeachMoonFrames");Slice(f,"SlotNormal",65,40,320,440);Slice(f,"SlotSelected",425,30,380,470);Slice(f,"MinimapRing",815,45,410,445);Slice(f,"ButtonPrimary",20,550,470,155,new Vector4(100,40,100,40));Slice(f,"ButtonPaper",495,550,470,155,new Vector4(100,40,100,40));Slice(f,"TabSelected",975,520,230,235);Slice(f,"DetailPaper",35,765,390,450,new Vector4(55,65,55,65));Slice(f,"StartBand",470,890,720,150);Slice(f,"GaugeFrame",495,1075,700,95);
var icons=Import("PeachMoonIcons");string[] names={"Bag","Craft","Journal","Settings","Equipment","Food","Material","Map","Language","Notice","Exit","Close"};for(int i=0;i<12;i++){float[] ys={140,480,820};Slice(icons,"Icon"+names[i],i%4*320,ys[i/4],320,i/4==0?315:310);}AssetDatabase.SaveAssets();}
public static void Ingame(){var scene=EditorSceneManager.OpenScene("Assets/00_ProjectD/01_Scenes/Production/Ingame.unity");var root=GameObject.Find("RpgCanvas").transform;var inv=root.Find("Inventory");
foreach(var item in inv.Find("Grid").GetComponentsInChildren<RpgItemButton>(true)){var t=item.transform;item.ConfigureSkin(S("SlotNormal"),S("SlotSelected"));Skin(t,"SlotNormal");C<UnityEngine.UI.Image>(t).raycastTarget=true;C<UnityEngine.UI.Button>(t).targetGraphic=C<UnityEngine.UI.Image>(t);t.Find("Fill").gameObject.SetActive(false);t.Find("QuantityPaper").gameObject.SetActive(false);P(t.Find("Art"),10,17,108,106);P(t.Find("Count"),20,129,88,17);C<TMP_Text>(t.Find("Count")).fontSize=16;P(t.Find("Equipped"),20,17,85,19);C<TMP_Text>(t.Find("Equipped")).fontSize=11;}
foreach(var item in root.Find("HUD/Quickbar").GetComponentsInChildren<RpgItemButton>(true)){var t=item.transform;item.ConfigureSkin(S("SlotNormal"),S("SlotSelected"));Skin(t,"SlotNormal");t.Find("Fill").gameObject.SetActive(false);C<UnityEngine.UI.Image>(t).raycastTarget=true;C<UnityEngine.UI.Button>(t).targetGraphic=C<UnityEngine.UI.Image>(t);P(t.Find("Art"),5,5,50,44);P(t.Find("Count"),22,45,25,10);C<TMP_Text>(t.Find("Count")).fontSize=10;C<TMP_Text>(t.Find("Count")).color=new Color(.2f,.22f,.26f);P(t.Find("Key"),7,7,18,14);C<TMP_Text>(t.Find("Key")).fontSize=10;}
var detail=inv.Find("Detail");Skin(detail,"DetailPaper",true);detail.Find("ItemHeader").gameObject.SetActive(false);detail.Find("Rule").gameObject.SetActive(false);P(detail.Find("Title"),38,35,470,50);C<TMP_Text>(detail.Find("Title")).color=new Color(.22f,.24f,.31f);P(detail.Find("Category"),40,88,460,30);C<TMP_Text>(detail.Find("Category")).color=new Color(.42f,.44f,.49f);P(detail.Find("Art"),168,115,260,230);P(detail.Find("Description"),40,367,470,130);P(detail.Find("Count"),40,520,470,110);Skin(detail.Find("Action"),"ButtonPrimary",true);C<TMP_Text>(detail.Find("Action/Label")).color=new Color(.96f,.95f,.91f);P(detail.Find("Action"),0,710,550,74);
Skin(inv.Find("Sort"),"ButtonPaper",true);C<TMP_Text>(inv.Find("Sort/Label")).color=new Color(.22f,.24f,.31f);
string[] tabs={"Bag","Equipment","Food","Material"};for(int i=0;i<4;i++){var t=inv.Find("Filters/Filter"+i);Skin(t,"TabSelected");Icon(t.Find("Glyph"),"Icon"+tabs[i]);P(t.Find("Glyph"),12,10,34,34);}Icon(inv.Find("Filters/Craft/Glyph"),"IconCraft");
var hud=root.Find("HUD");foreach(string name in new[]{"Bag","Craft","Journal","Settings"}){var t=hud.Find("Navigation/"+name+"/Glyph");Icon(t,"Icon"+name);P(t,10,0,44,44);}
var map=hud.Find("Region/MapFrame");C<UnityEngine.UI.Image>(map).color=Color.clear;var ring=Child(map,"IllustratedRing");P(ring,-12,-15,196,213);Skin(ring,"MinimapRing");ring.SetAsLastSibling();map.Find("Marker").SetAsLastSibling();map.Find("North").SetAsLastSibling();
foreach(string name in new[]{"HealthTrack","FoodTrack"}){var track=hud.Find("Vitals/"+name);var frame=Child(track,"IllustratedFrame");var rr=(RectTransform)frame;rr.anchorMin=Vector2.zero;rr.anchorMax=Vector2.one;rr.offsetMin=new Vector2(-18,-11);rr.offsetMax=new Vector2(18,11);Skin(frame,"GaugeFrame");}
foreach(var button in root.GetComponentsInChildren<UnityEngine.UI.Button>(true)){var t=button.transform;if(t.name=="Close"){Skin(t,"TabSelected");if(t.Find("Icon"))Icon(t.Find("Icon"),"IconClose");}if(t.name=="Confirm"||t.name=="OpenBag"||t.name=="OpenCrafting")Skin(t,"ButtonPaper",true);}
foreach(string path in new[]{"Settings/Panel","Journal/Workspace/Page"})Skin(root.Find(path),"DetailPaper",true);
C<RpgUiController>(root).Bind();EditorSceneManager.SaveScene(scene);}
public static void Login(){var scene=EditorSceneManager.OpenScene("Assets/00_ProjectD/01_Scenes/Production/Login.unity");var root=GameObject.Find("LoginCanvas").transform;var start=root.Find("LoginActions/LoginButton");Skin(start,"StartBand");((RectTransform)start).sizeDelta=new Vector2(860,120);C<TMP_Text>(start.Find("Label")).color=new Color(.98f,.97f,.93f);
string[] names={"LanguageButton","SettingsButton","NoticesButton","ExitButton"};string[] icons={"Language","Settings","Notice","Exit"};for(int i=0;i<4;i++){var t=root.Find("UtilityNavigation/"+names[i]);C<UnityEngine.UI.Image>(t).color=Color.clear;Icon(t.Find("Icon"),"Icon"+icons[i]);var r=(RectTransform)t.Find("Icon");r.sizeDelta=new Vector2(40,40);}
EditorSceneManager.SaveScene(scene);}
}}
